mapper.select:
SELECT *
FROM shopion.tOrdOrder

    AND ChnlCode = #{pChnlCode}
    AND OrderNo = #{pOrderNo}
    AND OrderName LIKE CONCAT('%',#{pOrderName},'%')
    AND RecverName LIKE CONCAT('%',#{pRecverName},'%')
    AND CustId = #{pCustId}


    ORDER BY ${sidx} ${sord}
    ORDER BY OrderNo DESC

SELECT O.*, OPay.PayType AS payType, CV.ConstrValDesc AS payTypeName, OPay.CardComp AS cardComp, OPay.ReciptBank AS reciptBank, OPay.ApprovNo AS approvNo, OPay.ReciptName AS reciptName, OPay.PayFee AS payFee FROM shopion.tOrdOrder O INNER JOIN shopion.tOrdOrderPay OPay ON O.OrderNo = OPay.OrderNo INNER JOIN (SELECT * FROM wizardn.tCodConstrVal WHERE ConstrCode = 'cPayType') CV ON OPay.PayType = CV.ConstrVal
AND O.OrderNo = #{pOrderNo} AND O.OrderName LIKE CONCAT('%',#{pOrderName},'%') AND O.RecverName LIKE CONCAT('%',#{pRecverName},'%') AND O.CustId = #{pCustId}
AND (OPay.PayDate >= DATE_FORMAT(#{startDate}, '%Y%m%d') AND OPay.PayDate < ADDDATE(DATE_FORMAT(#{endDate}, '%Y%m%d'), INTERVAL 1 DAY))
ORDER BY O.${sidx} ${sord}

mapper.update:
UPDATE shopion.tOrdOrder SET
    OrderState = #{orderState}, OrderCancelDate = NOW(),
    ChangeDate = NOW(), ChangeId = #{changeId}, ChangeName = #{changeName}
WHERE OrderNo = #{orderNo}
AND OrderState != '결제오류'
